// Public home page: a simple Gumroad-style grid of product cards.

import { esc } from "./ops.js";

interface ShelfProduct {
  slug: string;
  title: string;
  description: string;
  priceCents: number;
  type: string;
}

const TYPE_COLORS: Record<string, string> = {
  spreadsheet: "#23a094",
  rules_pack: "#90a8ed",
  prompt_pack: "#ffc900",
  code_kit: "#ff90e8",
  guide: "#f1f333",
  planner: "#ffb3a7",
};

export const STORE_CSS = `
:root{--bg:#f4f4f0;--ink:#000;--muted:#545454;--pink:#ff90e8}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.5 system-ui,-apple-system,"Helvetica Neue",sans-serif}
a{color:inherit}
.top{background:#fff;border-bottom:1px solid var(--ink)}
.top .in{max-width:1120px;margin:0 auto;padding:14px 16px;display:flex;align-items:center;gap:16px}
.logo{font-weight:800;font-size:22px;letter-spacing:-.03em;text-decoration:none}
.top .sp{flex:1}.top nav a{text-decoration:none;font-size:15px}.top nav a:hover{text-decoration:underline}
.wrap{max-width:1120px;margin:0 auto;padding:32px 16px 72px}
.btn{display:inline-block;background:var(--pink);color:var(--ink);border:1px solid var(--ink);border-radius:4px;padding:12px 20px;font-weight:600;font-size:16px;text-decoration:none;cursor:pointer;transition:transform .12s,box-shadow .12s}
.btn:hover{transform:translate(-4px,-4px);box-shadow:4px 4px 0 var(--ink)}
.box{background:#fff;border:1px solid var(--ink);border-radius:4px}
.pill{display:inline-block;border:1px solid var(--ink);border-radius:999px;padding:2px 10px;font-size:13px;background:#fff}
.price-tag{display:inline-block;background:var(--pink);border:1px solid var(--ink);padding:2px 10px;font-weight:700;font-size:15px;position:relative;margin-right:10px}
.price-tag::after{content:"";position:absolute;right:-9px;top:50%;width:14px;height:14px;background:var(--pink);border-right:1px solid var(--ink);border-top:1px solid var(--ink);transform:translateY(-50%) rotate(45deg)}
.alert{background:#fff7d6;border:1px solid var(--ink);border-radius:4px;padding:14px 16px;margin-bottom:16px}
.alert.success{background:#d8f5e8}
`;

export function topBar(): string {
  return `<header class="top"><div class="in"><a class="logo" href="/">autoshelf</a><span class="sp"></span>
<nav><a href="/ops">Watch the agents</a></nav></div></header>`;
}

export function renderHome(items: ShelfProduct[], src: string): string {
  const srcQs = src && src !== "direct" ? `?src=${encodeURIComponent(src)}` : "";
  const cards = items
    .map((p) => {
      const kind = p.type.replace("_", " ");
      const color = TYPE_COLORS[p.type] ?? "#e5e5e5";
      return `<a class="card" href="/p/${esc(p.slug)}${srcQs}">
  <div class="cover" style="background:${color}"><span>${esc(p.title)}</span></div>
  <div class="body"><h3>${esc(p.title)}</h3><p>${esc(p.description.slice(0, 110))}</p></div>
  <div class="foot"><span class="price-tag">$${(p.priceCents / 100).toFixed(0)}</span><span class="pill">${esc(kind)}</span></div>
</a>`;
    })
    .join("");

  return `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>AutoShelf — digital goods, run by AI agents</title>
<meta name="description" content="Spreadsheets, prompt packs and coding rules. Instant download.">
<style>${STORE_CSS}
.hero{border-bottom:1px solid var(--ink);background:#fff}
.hero .in{max-width:1120px;margin:0 auto;padding:48px 16px}
.hero h1{margin:0 0 10px;font-size:clamp(32px,5vw,56px);line-height:1.05;letter-spacing:-.03em}
.hero p{margin:0;color:var(--muted);font-size:18px;max-width:560px}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:20px}
.card{display:flex;flex-direction:column;background:#fff;border:1px solid var(--ink);border-radius:4px;text-decoration:none;overflow:hidden;transition:transform .12s,box-shadow .12s}
.card:hover{transform:translate(-4px,-4px);box-shadow:4px 4px 0 var(--ink)}
.cover{aspect-ratio:1/1;border-bottom:1px solid var(--ink);display:flex;align-items:flex-end;padding:16px}
.cover span{font-weight:800;font-size:22px;line-height:1.1;letter-spacing:-.02em}
.card .body{padding:14px 16px;flex:1}
.card h3{margin:0 0 6px;font-size:17px;line-height:1.3}
.card p{margin:0;color:var(--muted);font-size:14px}
.card .foot{border-top:1px solid var(--ink);padding:12px 16px;display:flex;align-items:center;gap:10px}
.section-title{font-size:20px;margin:0 0 16px}
</style></head><body>
${topBar()}
<section class="hero"><div class="in"><h1>Digital goods,<br>run by AI agents.</h1>
<p>Spreadsheets, prompt packs and coding rules. Pay once, download instantly.</p></div></section>
<main class="wrap"><h2 class="section-title">All products</h2>
<div class="grid">${cards || "<p>No products yet.</p>"}</div></main>
</body></html>`;
}

