import { Hono } from "hono";
import { serve } from "@hono/node-server";
import { getDb } from "../core/db.js";
import { products, orders, channels } from "../core/schema.js";
import { eq } from "drizzle-orm";
import {
  createCheckoutSession,
  parseWebhookEvent,
  verifyWebhookSignature,
} from "./payments.js";
import { getOrderByToken, generateDownloadToken } from "./delivery.js";
import { recordRevenue, recordFee } from "../services/ledger.js";
import { config } from "../core/config.js";
import { randomUUID } from "crypto";
import fs from "fs";
import path from "path";
import type { Context } from "hono";
import { visits } from "../core/schema.js";
import { seedStore } from "../core/seed.js";
import { ops, esc } from "./ops.js";
import { renderHome, STORE_CSS, topBar } from "./home.js";

const app = new Hono();
seedStore();
app.route("/ops", ops);

// Record where each visitor came from: ?src=x&post=abc from agent posts, else the referrer.
function trackVisit(c: Context, productSlug?: string): string {
  let src = c.req.query("src") ?? "";
  if (!src) {
    const ref = c.req.header("referer");
    const host = c.req.header("host");
    try {
      const refHost = ref ? new URL(ref).host : "";
      src = refHost && refHost !== host ? refHost : "direct";
    } catch {
      src = "direct";
    }
  }
  src = src.slice(0, 64);
  getDb()
    .insert(visits)
    .values({
      id: randomUUID(),
      path: c.req.path,
      productSlug: productSlug ?? null,
      src,
      postId: c.req.query("post")?.slice(0, 16) ?? null,
      ts: new Date(),
    })
    .run();
  return src;
}

// ── Templates ─────────────────────────────────────────────────────────────────

function layout(title: string, body: string): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${title} — AutoShelf</title>
  <style>${STORE_CSS}
    .container { max-width: 900px; margin: 0 auto; padding: 32px 16px 72px; }
    .card { background: #fff; border: 1px solid #000; border-radius: 4px; padding: 24px; margin-bottom: 16px; }
    .price { font-size: 2rem; font-weight: 700; }
    .badge { display: inline-block; border: 1px solid #000; border-radius: 999px; padding: 2px 10px; font-size: 13px; background: #fff; }
    ul.benefits { list-style: none; margin: 1rem 0; padding: 0; }
    ul.benefits li::before { content: "✓ "; font-weight: 700; }
    .product { display: grid; grid-template-columns: 1.4fr 1fr; border: 1px solid #000; border-radius: 4px; background: #fff; overflow: hidden; }
    .product .cover { aspect-ratio: 16/9; grid-column: 1 / -1; border-bottom: 1px solid #000; display: flex; align-items: flex-end; padding: 24px; background: #ff90e8; }
    .product .cover span { font-weight: 800; font-size: clamp(24px, 4vw, 40px); line-height: 1.05; letter-spacing: -.02em; }
    .product .main { padding: 24px; border-right: 1px solid #000; }
    .product .main h1 { margin: 0 0 12px; font-size: 28px; line-height: 1.2; }
    .product .main p { color: #545454; margin: 0; }
    .product .side { padding: 24px; display: flex; flex-direction: column; gap: 16px; }
    .product .side .btn { text-align: center; }
    @media (max-width: 640px) { .product { grid-template-columns: 1fr; } .product .main { border-right: 0; border-bottom: 1px solid #000; } }
  </style>
</head>
<body>
  ${topBar()}
  <div class="container">${body}</div>
</body>
</html>`;
}

// ── Routes ────────────────────────────────────────────────────────────────────

app.get("/", (c) => {
  const src = trackVisit(c);
  const liveProducts = getDb().select().from(products).where(eq(products.status, "live")).all();
  return c.html(renderHome(liveProducts, src));
});

app.get("/p/:slug", (c) => {
  const db = getDb();
  const product = db
    .select()
    .from(products)
    .where(eq(products.slug, c.req.param("slug")))
    .get();

  if (!product) return c.html(layout("Not Found", "<p>Product not found.</p>"), 404);
  trackVisit(c, product.slug);

  return c.html(
    layout(
      esc(product.title),
      `<div class="product">
        <div class="cover"><span>${esc(product.title)}</span></div>
        <div class="main">
          <h1>${esc(product.title)}</h1>
          <p>${esc(product.description)}</p>
        </div>
        <div class="side">
          <div><span class="price-tag">$${(product.priceCents / 100).toFixed(2)}</span> <span class="badge">${product.type.replace("_", " ")}</span></div>
          <a href="/checkout/${product.id}" class="btn">I want this!</a>
          <small style="color:#545454">Instant download after payment.</small>
        </div>
      </div>`
    )
  );
});

app.get("/checkout/:productId", async (c) => {
  const db = getDb();
  const product = db
    .select()
    .from(products)
    .where(eq(products.id, c.req.param("productId")))
    .get();

  if (!product) return c.html(layout("Not Found", "<p>Product not found.</p>"), 404);

  const host = c.req.header("host") ?? "localhost:3000";
  const proto = host.includes("localhost") ? "http" : "https";

  try {
    const session = await createCheckoutSession({
      productId: product.id,
      productTitle: product.title,
      priceCents: product.priceCents,
      successUrl: `${proto}://${host}/checkout/success?product_id=${product.id}`,
      cancelUrl: `${proto}://${host}/p/${product.slug}`,
      metadata: { product_id: product.id },
    });

    return c.redirect(session.url);
  } catch (err) {
    return c.html(
      layout(
        "Error",
        `<div class="alert">Checkout error: ${err instanceof Error ? err.message : "unknown"}</div>`
      ),
      500
    );
  }
});

app.get("/checkout/success", async (c) => {
  const productId = c.req.query("product_id");
  const isMock = c.req.query("mock") === "1";

  if (isMock && productId) {
    const db = getDb();
    const product = db
      .select()
      .from(products)
      .where(eq(products.id, productId))
      .get();

    // Create mock order
    const orderId = randomUUID();
    const { token, expiresAt } = generateDownloadToken(orderId);

    db.insert(orders)
      .values({
        id: orderId,
        productId: productId,
        channelId: "channel_web",
        pricePaidCents: product?.priceCents ?? 0,
        discountPct: 0,
        status: "delivered",
        dodoRef: `mock_${orderId}`,
        simDay: 0,
        downloadToken: token,
        tokenExpiresAt: expiresAt,
      })
      .run();

    if (product) {
      const feeCents = Math.floor(
        product.priceCents * (config.platformFeePct / 100)
      );
      recordRevenue(0, product.priceCents, orderId);
      recordFee(0, feeCents, orderId);
    }

    return c.html(
      layout(
        "Purchase Successful",
        `<div class="card alert success">
          <h2>Thank you for your purchase!</h2>
          <p style="margin:1rem 0">Order ID: <code>${orderId}</code></p>
          <a href="/download/${token}" class="btn">Download Your Product</a>
        </div>`
      )
    );
  }

  return c.html(
    layout(
      "Purchase Successful",
      `<div class="card alert success">
        <h2>Thank you for your purchase!</h2>
        <p>Check your email for your download link.</p>
      </div>`
    )
  );
});

app.post("/webhook/dodo", async (c) => {
  const body = await c.req.text();
  const sig = c.req.header("dodo-signature") ?? "";

  if (!verifyWebhookSignature(body, sig)) {
    return c.json({ error: "Invalid signature" }, 401);
  }

  let event;
  try {
    event = parseWebhookEvent(body);
  } catch {
    return c.json({ error: "Invalid payload" }, 400);
  }

  if (event.type === "payment.succeeded") {
    const db = getDb();
    const productId = event.data.metadata?.["product_id"] as string | undefined;
    if (productId) {
      const product = db
        .select()
        .from(products)
        .where(eq(products.id, productId))
        .get();

      if (product) {
        const orderId = randomUUID();
        const { token, expiresAt } = generateDownloadToken(orderId);
        db.insert(orders)
          .values({
            id: orderId,
            productId,
            channelId: "channel_web",
            pricePaidCents: event.data.amount ?? product.priceCents,
            discountPct: 0,
            status: "delivered",
            dodoRef: event.data.id,
            simDay: 0,
            downloadToken: token,
            tokenExpiresAt: expiresAt,
          })
          .run();

        const feeCents = Math.floor(
          product.priceCents * (config.platformFeePct / 100)
        );
        recordRevenue(0, product.priceCents, orderId);
        recordFee(0, feeCents, orderId);
      }
    }
  }

  return c.json({ ok: true });
});

app.get("/download/:token", (c) => {
  const token = c.req.param("token");
  const order = getOrderByToken(token);

  if (!order) {
    return c.html(
      layout(
        "Invalid Link",
        `<div class="alert">This download link is invalid or has expired. Contact support.</div>`
      ),
      404
    );
  }

  if (order.tokenExpiresAt && order.tokenExpiresAt < new Date()) {
    return c.html(
      layout(
        "Link Expired",
        `<div class="alert">This download link has expired. Please contact support for a new link.</div>`
      ),
      410
    );
  }

  const db = getDb();
  const product = db
    .select()
    .from(products)
    .where(eq(products.id, order.productId))
    .get();

  if (!product?.artifactPath) {
    return c.html(
      layout("Error", "<p>Product files not found. Contact support.</p>"),
      500
    );
  }

  const artifactDir = path.resolve(product.artifactPath);
  if (!fs.existsSync(artifactDir)) {
    return c.html(
      layout("Error", "<p>Product files not available yet. Contact support.</p>"),
      500
    );
  }

  // List files for download
  const files = fs.readdirSync(artifactDir).filter((f) => !f.startsWith("."));
  const fileList = files
    .map((f) => `<li><a href="/download/${token}/file/${f}">${f}</a></li>`)
    .join("");

  return c.html(
    layout(
      "Download",
      `<div class="card">
        <h2>Your Download: ${product.title}</h2>
        <p style="margin:1rem 0;color:#6b7280;">Order ${order.id}</p>
        <ul style="margin:1rem 0;padding-left:1.5rem;">${fileList}</ul>
        <p style="color:#6b7280;font-size:.85rem;">Links expire 72 hours after purchase.</p>
      </div>`
    )
  );
});

app.get("/download/:token/file/:filename", (c) => {
  const { token, filename } = c.req.param();
  const order = getOrderByToken(token);

  if (!order || (order.tokenExpiresAt && order.tokenExpiresAt < new Date())) {
    return c.text("Unauthorized", 401);
  }

  const db = getDb();
  const product = db
    .select()
    .from(products)
    .where(eq(products.id, order.productId))
    .get();

  if (!product?.artifactPath) return c.text("Not found", 404);

  // Sanitize filename to prevent path traversal
  const safe = path.basename(filename);
  const filePath = path.join(path.resolve(product.artifactPath), safe);

  if (!fs.existsSync(filePath)) return c.text("Not found", 404);

  const content = fs.readFileSync(filePath);
  c.header("Content-Disposition", `attachment; filename="${safe}"`);
  return c.body(content as unknown as ReadableStream);
});

// ── Start server ──────────────────────────────────────────────────────────────

const port = parseInt(process.env["PORT"] ?? "3000");
console.log(`[store] Listening on http://localhost:${port}`);

serve({ fetch: app.fetch, port });

export default app;
// /ops — watch the agents work. Lists check-ins and replays each agent's
// thinking, tool calls and tool results, with sub-agent runs nested inline.

import { Hono } from "hono";
import { sqlAll } from "../core/db.js";
import { liveCheckIn } from "../agents/run-live.js";

export const ops = new Hono();

export function esc(s: unknown): string {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

const AGENT_COLOR: Record<string, string> = {
  operator: "#818cf8",
  analytics: "#2dd4bf",
  content: "#fbbf24",
  support: "#fb7185",
};

interface RunRow {
  id: string;
  parent_id: string | null;
  agent: string;
  task: string;
  status: string;
  result: string | null;
  cost_cents: number;
  sim_day: number;
  started_at: number;
  ended_at: number | null;
}

interface StepRow {
  seq: number;
  kind: string;
  tool_name: string | null;
  content: string;
  is_error: number;
  child_run_id: string | null;
}

function page(title: string, body: string, refresh = false) {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
${refresh ? '<meta http-equiv="refresh" content="3">' : ""}
<title>${esc(title)} · AutoShelf ops</title>
<style>
:root{--bg:#0b0d12;--panel:#12151d;--line:#232836;--text:#e6e8ee;--muted:#8b93a7}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.55 system-ui,-apple-system,sans-serif}
a{color:inherit}header{display:flex;gap:16px;align-items:center;padding:14px 20px;border-bottom:1px solid var(--line)}
header b{font-size:16px}header .sp{flex:1}main{max-width:980px;margin:0 auto;padding:20px 16px 80px}
.btn{background:#4f46e5;color:#fff;border:0;border-radius:8px;padding:8px 14px;font-weight:600;cursor:pointer}
table{width:100%;border-collapse:collapse}td,th{padding:10px 8px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}
th{color:var(--muted);font-weight:500;font-size:12px;text-transform:uppercase;letter-spacing:.04em}
.tag{display:inline-block;padding:1px 8px;border-radius:999px;font-size:12px;font-weight:600;color:#0b0d12}
.muted{color:var(--muted)}.run{border-left:3px solid var(--c);background:var(--panel);border-radius:8px;padding:12px 14px;margin:10px 0}
.run>.head{display:flex;gap:10px;align-items:baseline;flex-wrap:wrap;margin-bottom:6px}
.step{margin:8px 0;padding:8px 10px;border-radius:6px;background:#0e1118;border:1px solid var(--line)}
.think{font-style:italic;color:#c4b5fd;background:#151225;border-color:#2b2347}
.call{font-family:ui-monospace,Menlo,monospace;font-size:12.5px}.call b{color:var(--c)}
.err{border-color:#7f1d1d;background:#1c0f12;color:#fca5a5}.answer{border-color:#14532d;background:#0d1a12}
pre{margin:6px 0 0;white-space:pre-wrap;word-break:break-word;font:12px/1.5 ui-monospace,Menlo,monospace;color:#cbd5e1;max-height:320px;overflow:auto}
summary{cursor:pointer;color:var(--muted);font-size:12.5px}.label{font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);margin-bottom:2px}
.legend span{margin-right:10px}
</style></head><body>
<header><b><a href="/ops" style="text-decoration:none">AutoShelf · agent activity</a></b>
<span class="legend muted">${Object.entries(AGENT_COLOR)
    .map(([a, c]) => `<span><span class="tag" style="background:${c}">${a}</span></span>`)
    .join("")}</span><span class="sp"></span><a href="/" class="muted">Store →</a></header>
<main>${body}</main></body></html>`;
}

const money = (c: number) => `$${(c / 100).toFixed(3)}`;
const time = (ms: number) => new Date(ms).toLocaleString();
const dur = (r: RunRow) => (r.ended_at ? `${((r.ended_at - r.started_at) / 1000).toFixed(1)}s` : "running…");

ops.get("/", (c) => {
  const runs = sqlAll<RunRow & { children: number; steps: number }>(`
    SELECT r.*,
      (SELECT COUNT(*) FROM agent_runs k WHERE k.parent_id = r.id) AS children,
      (SELECT COUNT(*) FROM agent_steps s WHERE s.agent_run_id = r.id) AS steps
    FROM agent_runs r WHERE r.parent_id IS NULL
    ORDER BY r.started_at DESC LIMIT 50`);
  const anyRunning = runs.some((r) => r.status === "running");
  const rows = runs
    .map(
      (r) => `<tr>
      <td><span class="tag" style="background:${AGENT_COLOR[r.agent] ?? "#999"}">${esc(r.agent)}</span></td>
      <td><a href="/ops/run/${r.id}">${esc(r.task)}</a><div class="muted">${esc((r.result ?? "").split("\n")[0]).slice(0, 160)}</div></td>
      <td>${r.children} helpers · ${r.steps} steps</td>
      <td>${esc(r.status)}<div class="muted">${dur(r)}</div></td>
      <td class="muted">${time(r.started_at)}</td></tr>`
    )
    .join("");
  return c.html(
    page(
      "Activity",
      `<div style="display:flex;align-items:center;gap:12px;margin-bottom:16px">
        <h2 style="margin:0;flex:1">Check-ins</h2>
        <form method="post" action="/ops/check-in"><button class="btn">Run agents now</button></form></div>
      <table><tr><th>Agent</th><th>Task / outcome</th><th>Work</th><th>Status</th><th>Started</th></tr>
      ${rows || `<tr><td colspan="5" class="muted">No agent runs yet. Click “Run agents now”.</td></tr>`}</table>`,
      anyRunning
    )
  );
});

let checkInRunning = false;
ops.post("/check-in", (c) => {
  if (!checkInRunning) {
    checkInRunning = true;
    liveCheckIn()
      .catch((e) => console.error("[ops] check-in failed", e))
      .finally(() => (checkInRunning = false));
  }
  return c.redirect("/ops");
});

function renderRun(runId: string, depth = 0): string {
  const [r] = sqlAll<RunRow>(`SELECT * FROM agent_runs WHERE id = ?`, runId);
  if (!r || depth > 5) return "";
  const steps = sqlAll<StepRow>(`SELECT * FROM agent_steps WHERE agent_run_id = ? ORDER BY seq`, runId);
  const color = AGENT_COLOR[r.agent] ?? "#999";
  const body = steps
    .map((s) => {
      if (s.kind === "thinking")
        return `<div class="step think"><div class="label">thinking</div>${esc(s.content)}</div>`;
      if (s.kind === "tool_call")
        return `<div class="step call"><div class="label">tool call</div><b>${esc(s.tool_name)}</b><pre>${esc(s.content)}</pre></div>`;
      if (s.kind === "tool_result") {
        const child = s.child_run_id ? renderRun(s.child_run_id, depth + 1) : "";
        return `<div class="step call ${s.is_error ? "err" : ""}"><details ${s.is_error ? "open" : ""}><summary>${s.is_error ? "tool error" : "result"} from <b>${esc(s.tool_name)}</b> (${s.content.length} chars)</summary><pre>${esc(s.content)}</pre></details></div>${child}`;
      }
      if (s.kind === "error") return `<div class="step err"><div class="label">error</div>${esc(s.content)}</div>`;
      return `<div class="step answer"><div class="label">answer</div>${esc(s.content).replace(/\n/g, "<br>")}</div>`;
    })
    .join("");
  return `<div class="run" style="--c:${color}">
    <div class="head"><span class="tag" style="background:${color}">${esc(r.agent)}</span>
    <span>${esc(r.task)}</span><span class="muted">· ${esc(r.status)} · ${dur(r)} · AI cost ${money(r.cost_cents)}</span></div>
    ${body || '<div class="muted">starting…</div>'}</div>`;
}

ops.get("/run/:id", (c) => {
  const id = c.req.param("id");
  const [r] = sqlAll<RunRow>(`SELECT * FROM agent_runs WHERE id = ?`, id);
  if (!r) return c.html(page("Not found", "<p>No such run.</p>"), 404);
  const running = sqlAll(`SELECT 1 FROM agent_runs WHERE status='running'`).length > 0;
  return c.html(
    page(
      `${r.agent} run`,
      `<p class="muted"><a href="/ops">← all check-ins</a> · day ${r.sim_day} · ${time(r.started_at)}</p>${renderRun(id)}`,
      running
    )
  );
});
