// Tracing via the neatlogs SDK. Each check-in is a WORKFLOW trace; agents, model
// calls and tools nest inside it as AGENT, LLM and TOOL spans, so neatlogs shows
// the whole tree with each model call's thinking. Without NEATLOGS_API_KEY,
// spans are printed to the console instead.

import { init, shutdown, trace } from "neatlogs";

export type SpanKind = "WORKFLOW" | "AGENT" | "LLM" | "TOOL" | "CHAIN";
type Attr = string | number | boolean;

export interface Span {
  id: string;
  name: string;
  tags: Record<string, Attr>;
  startedAt: number;
  /** Attach attributes to the span (no-op without neatlogs). */
  set(attrs: Record<string, Attr | undefined>): void;
}

const apiKey = process.env["NEATLOGS_API_KEY"];
let ready: Promise<void> | null = null;

function ensureInit(): Promise<void> {
  ready ??= init({
    apiKey,
    workflowName: "autoshelf",
    ...(process.env["NEATLOGS_ENDPOINT"] ? { endpoint: process.env["NEATLOGS_ENDPOINT"] } : {}),
  }).catch((err) => {
    console.error("[trace] neatlogs init failed, tracing disabled:", err);
  });
  return ready;
}

function kindFor(name: string): SpanKind {
  if (name.startsWith("agent:")) return "AGENT";
  if (name.startsWith("llm:")) return "LLM";
  if (name.startsWith("tool:")) return "TOOL";
  if (name.startsWith("live:") || name.startsWith("sim:")) return "WORKFLOW";
  return "CHAIN";
}

function makeId(): string {
  return Math.random().toString(36).slice(2, 10);
}

export async function withSpan<T>(
  name: string,
  tags: Record<string, Attr>,
  fn: (span: Span) => Promise<T>,
  _parentId?: string,
  kind: SpanKind = kindFor(name)
): Promise<T> {
  const startedAt = Date.now();

  if (!apiKey) {
    const span: Span = { id: makeId(), name, tags, startedAt, set: () => {} };
    try {
      const result = await fn(span);
      console.log(`[trace] ${name} ${Date.now() - startedAt}ms`, Object.keys(tags).length ? tags : "");
      return result;
    } catch (err) {
      console.log(`[trace] ${name} ${Date.now() - startedAt}ms ERROR: ${err instanceof Error ? err.message : err}`);
      throw err;
    }
  }

  await ensureInit();
  // LLM spans carry their messages as attributes, so skip the generic input capture there.
  return trace({ name, kind, ...(kind === "LLM" ? {} : { input: tags }), attributes: tags }, async (otel) => {
    const span: Span = {
      id: otel.spanContext().spanId,
      name,
      tags,
      startedAt,
      set(attrs) {
        for (const [k, v] of Object.entries(attrs)) if (v !== undefined) otel.setAttribute(k, v);
      },
    };
    return fn(span);
  });
}

/** Send any buffered spans. Call before a short-lived script exits. */
export async function shutdownTracing(): Promise<void> {
  if (ready) {
    await ready;
    await shutdown();
  }
}

// Amazon Bedrock Converse client for open-weight models (GLM, DeepSeek, ...).
// Each call is an LLM span in neatlogs carrying the messages, the model's
// reasoning ("thinking"), tool calls and token usage.
//
// Auth: AWS_BEARER_TOKEN_BEDROCK (a Bedrock API key) or the standard AWS
// credential chain (AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY, profile, SSO).

import {
  BedrockRuntimeClient,
  ConverseCommand,
  type ContentBlock,
  type Message,
  type Tool,
} from "@aws-sdk/client-bedrock-runtime";
import { config } from "./config.js";
import { withSpan } from "./trace.js";

export interface JsonSchema {
  type: "object";
  properties?: Record<string, unknown>;
  required?: string[];
  [key: string]: unknown;
}

export interface ToolDef {
  name: string;
  description: string;
  input_schema: JsonSchema;
}

export interface ToolUse {
  id: string;
  name: string;
  input: Record<string, unknown>;
}

export interface ConverseResult {
  model: string;
  text: string;
  reasoning: string;
  toolUses: ToolUse[];
  /** The assistant turn to append to the conversation (reasoning stripped). */
  message: Message;
  stopReason: string;
  inTokens: number;
  outTokens: number;
  costCents: number;
}

let _client: BedrockRuntimeClient | null = null;
function client(): BedrockRuntimeClient {
  _client ??= new BedrockRuntimeClient({ region: config.awsRegion });
  return _client;
}

// Some open models return reasoning inline as <think>…</think> instead of a reasoning block.
const THINK_TAG = /<think>([\s\S]*?)<\/think>/g;

/** "us.zai.glm-5.3" → "zai", "deepseek.v3.2" → "deepseek" */
function vendorOf(model: string): string {
  const parts = model.split(".");
  return ["us", "eu", "apac", "global"].includes(parts[0] ?? "") ? (parts[1] ?? "") : (parts[0] ?? "");
}

function blockText(b: ContentBlock): string {
  if (b.text !== undefined) return b.text;
  if (b.toolUse) return `[tool call ${b.toolUse.name}] ${JSON.stringify(b.toolUse.input)}`;
  if (b.toolResult)
    return `[tool result${b.toolResult.status === "error" ? " (error)" : ""}] ${(b.toolResult.content ?? [])
      .map((c) => c.text ?? JSON.stringify(c.json ?? ""))
      .join("\n")}`;
  return "";
}

export async function converse(opts: {
  agent: string;
  system: string;
  messages: Message[];
  tools?: ToolDef[];
  effort?: "low" | "medium" | "high";
  model?: string;
  maxTokens?: number;
}): Promise<ConverseResult> {
  const model = opts.model ?? config.bedrockModel;
  const maxTokens = opts.maxTokens ?? config.bedrockMaxTokens;

  return withSpan(`llm:${opts.agent}`, { agent: opts.agent, model }, async (span) => {
    const tools: Tool[] | undefined = opts.tools?.length
      ? opts.tools.map((t) => ({
          toolSpec: { name: t.name, description: t.description, inputSchema: { json: t.input_schema as never } },
        }))
      : undefined;

    const res = await client().send(
      new ConverseCommand({
        modelId: model,
        system: [{ text: opts.system }],
        messages: opts.messages,
        ...(tools ? { toolConfig: { tools } } : {}),
        inferenceConfig: { maxTokens },
        // Models that take a reasoning-effort knob (GLM 5.3) get it passed through.
        ...(opts.effort && config.reasoningEffortModels.some((m) => model.includes(m))
          ? { additionalModelRequestFields: { reasoning_effort: opts.effort } }
          : {}),
      })
    );

    const content = res.output?.message?.content ?? [];
    const reasoningParts: string[] = [];
    const textParts: string[] = [];
    const toolUses: ToolUse[] = [];
    const keep: ContentBlock[] = [];

    for (const b of content) {
      if (b.reasoningContent) {
        const r = b.reasoningContent.reasoningText?.text;
        if (r) reasoningParts.push(r);
        continue; // don't send reasoning back in later turns
      }
      if (b.text !== undefined) {
        const visible = b.text.replace(THINK_TAG, (_, inner: string) => {
          reasoningParts.push(inner.trim());
          return "";
        });
        if (visible.trim()) {
          textParts.push(visible.trim());
          keep.push({ text: visible.trim() });
        }
        continue;
      }
      if (b.toolUse) {
        toolUses.push({
          id: b.toolUse.toolUseId ?? "",
          name: b.toolUse.name ?? "",
          input: (b.toolUse.input ?? {}) as Record<string, unknown>,
        });
      }
      keep.push(b);
    }

    const text = textParts.join("\n");
    const reasoning = reasoningParts.filter(Boolean).join("\n\n");
    const inTokens = res.usage?.inputTokens ?? 0;
    const outTokens = res.usage?.outputTokens ?? 0;
    const costCents =
      (inTokens / 1_000_000) * config.priceInPerMTokCents + (outTokens / 1_000_000) * config.priceOutPerMTokCents;

    // neatlogs LLM attributes (same keys its provider wrappers use).
    const attrs: Record<string, string | number | undefined> = {
      "neatlogs.llm.provider": "bedrock",
      "neatlogs.llm.system": vendorOf(model),
      "neatlogs.llm.model_name": model,
      "neatlogs.llm.max_tokens": maxTokens,
      "neatlogs.llm.input_messages.0.role": "system",
      "neatlogs.llm.input_messages.0.content": opts.system,
      "neatlogs.llm.output_messages.0.role": "assistant",
      "neatlogs.llm.output_messages.0.content": text,
      "neatlogs.llm.output_messages.0.thinking": reasoning || undefined,
      "neatlogs.llm.token_count.prompt": inTokens,
      "neatlogs.llm.token_count.completion": outTokens,
      "neatlogs.llm.token_count.total": inTokens + outTokens,
      "neatlogs.llm.finish_reason": res.stopReason,
      "output.value": text || toolUses.map((t) => `${t.name}(${JSON.stringify(t.input)})`).join("\n"),
    };
    opts.messages.forEach((m, i) => {
      attrs[`neatlogs.llm.input_messages.${i + 1}.role`] = m.role;
      attrs[`neatlogs.llm.input_messages.${i + 1}.content`] = (m.content ?? []).map(blockText).join("\n");
    });
    toolUses.forEach((t, j) => {
      attrs[`neatlogs.llm.tool_calls.${j}.id`] = t.id;
      attrs[`neatlogs.llm.tool_calls.${j}.name`] = t.name;
      attrs[`neatlogs.llm.tool_calls.${j}.arguments`] = JSON.stringify(t.input);
    });
    span.set(attrs);

    return {
      model,
      text,
      reasoning,
      toolUses,
      message: { role: "assistant", content: keep },
      stopReason: res.stopReason ?? "",
      inTokens,
      outTokens,
      costCents,
    };
  });
}

