// Per-run token budget. One team run (an operator check-in plus every helper it
// calls) may use at most RUN_TOKEN_BUDGET tokens (input + output, incl. thinking),
// split between the agents by share. The budget rides along the async call chain,
// so nested helper agents draw from the same run.

import { AsyncLocalStorage } from "async_hooks";
import { config } from "./config.js";

// Share of the run budget each agent may use. Unlisted agents draw from the run total only.
const SHARES: Record<string, number> = {
  operator: 0.35,
  analytics: 0.2,
  content: 0.3,
  support: 0.15,
};
// Calls made on an agent's behalf count against that agent.
const CHARGED_TO: Record<string, string> = { verify: "content" };

export class TokenBudgetExceeded extends Error {}

interface RunBudget {
  limit: number;
  used: number;
  byAgent: Map<string, number>;
}

const store = new AsyncLocalStorage<RunBudget>();

export async function withTokenBudget<T>(
  fn: () => Promise<T>,
  limit = config.runTokenBudget
): Promise<{ result: T; used: number; limit: number; byAgent: Record<string, number> }> {
  const budget: RunBudget = { limit, used: 0, byAgent: new Map() };
  const result = await store.run(budget, fn);
  return { result, used: budget.used, limit, byAgent: Object.fromEntries(budget.byAgent) };
}

const owner = (agent: string) => CHARGED_TO[agent] ?? agent;

/** Tokens this agent may still spend in the current run (Infinity outside a run). */
export function tokensLeft(agent: string): number {
  const b = store.getStore();
  if (!b) return Infinity;
  const total = b.limit - b.used;
  const share = SHARES[owner(agent)];
  if (share === undefined) return total;
  const agentLeft = Math.floor(b.limit * share) - (b.byAgent.get(owner(agent)) ?? 0);
  return Math.min(total, agentLeft);
}

export function chargeTokens(agent: string, tokens: number): void {
  const b = store.getStore();
  if (!b) return;
  b.used += tokens;
  b.byAgent.set(owner(agent), (b.byAgent.get(owner(agent)) ?? 0) + tokens);
}

/** Agent's share of the run budget, for messages. */
export function agentAllowance(agent: string): number {
  const b = store.getStore();
  const share = SHARES[owner(agent)];
  return b ? Math.floor(b.limit * (share ?? 1)) : Infinity;
}

