// Tools a swarm agent can use, grouped so a swarm can switch groups on or off.
// web: Crustdata web search + page read · code: sandboxed JavaScript · company: Crustdata company data.

import { spawn } from "child_process";
import { crustdata } from "../core/crustdata.js";
import type { JsonSchema } from "../core/model.js";

export type ToolGroup = "web" | "code" | "company";
export const TOOL_GROUPS: { id: ToolGroup; label: string; hint: string }[] = [
  { id: "web", label: "Web search & read pages", hint: "Crustdata web search, 1 credit per query/page" },
  { id: "code", label: "Code runner", hint: "Sandboxed JavaScript, 5s limit, no files or network" },
  { id: "company", label: "Company & people data", hint: "Crustdata company search" },
];

export interface SwarmTool {
  name: string;
  description: string;
  input_schema: JsonSchema;
  group: ToolGroup;
  run: (input: Record<string, unknown>) => Promise<unknown>;
}

const clip = (s: string, n: number) => (s.length > n ? s.slice(0, n) + `… [${s.length - n} more chars]` : s);

function htmlToText(html: string): string {
  return html
    .replace(/<(script|style|noscript|svg)[\s\S]*?<\/\1>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/\s+/g, " ")
    .trim();
}

// Runs inside `node --permission` (no file or child-process access), in a fresh vm
// context with no require/process/fetch, under a CPU timeout.
const RUNNER = `
const vm = require("vm");
let code = "";
process.stdin.on("data", (d) => (code += d));
process.stdin.on("end", () => {
  const out = [];
  const log = (...a) => out.push(a.map((x) => (typeof x === "string" ? x : JSON.stringify(x))).join(" "));
  const ctx = vm.createContext({ console: { log, error: log }, Math, JSON, BigInt, Number, String, Array, Object, Map, Set, Date });
  try {
    const r = vm.runInContext(code, ctx, { timeout: 4000 });
    if (r !== undefined) out.push("=> " + (typeof r === "string" ? r : JSON.stringify(r)));
  } catch (e) {
    out.push("ERROR: " + (e && e.message ? e.message : String(e)));
  }
  process.stdout.write(out.join("\\n"));
});
`;

export function runSandboxed(code: string): Promise<string> {
  return new Promise((resolve) => {
    const child = spawn(process.execPath, ["--permission", "--max-old-space-size=96", "-e", RUNNER], {
      stdio: ["pipe", "pipe", "pipe"],
    });
    let out = "";
    let err = "";
    const kill = setTimeout(() => child.kill("SIGKILL"), 6000);
    child.stdout.on("data", (d) => (out += d));
    child.stderr.on("data", (d) => (err += d));
    child.on("close", (codeNum) => {
      clearTimeout(kill);
      const text = out || (err ? `ERROR: ${err}` : codeNum === null ? "ERROR: killed (time limit)" : "(no output)");
      resolve(clip(text, 3000));
    });
    child.stdin.end(code);
  });
}

export const SWARM_TOOLS: SwarmTool[] = [
  {
    name: "web_search",
    group: "web",
    description: "Search the web. Returns titles, URLs and snippets.",
    input_schema: { type: "object", properties: { query: { type: "string" } }, required: ["query"] },
    run: async ({ query }) => {
      const { data } = await crustdata<any>("/web/search/live", { query: String(query) });
      return (data.results ?? []).slice(0, 6).map((r: any) => ({ title: r.title, url: r.url, snippet: r.snippet }));
    },
  },
  {
    name: "read_page",
    group: "web",
    description: "Read a web page as plain text (first ~4000 characters).",
    input_schema: { type: "object", properties: { url: { type: "string" } }, required: ["url"] },
    run: async ({ url }) => {
      const { data } = await crustdata<any[]>("/web/enrich/live", { urls: [String(url)] });
      const page = data?.[0];
      if (!page?.success) return { error: `could not read ${url}` };
      return { title: page.title, text: clip(htmlToText(String(page.content ?? "")), 4000) };
    },
  },
  {
    name: "run_code",
    group: "code",
    description:
      "Run JavaScript and get what it prints. Sandboxed: no files, no network, no require, 4 second limit. Use console.log for output. BigInt is available.",
    input_schema: { type: "object", properties: { code: { type: "string" } }, required: ["code"] },
    run: async ({ code }) => runSandboxed(String(code)),
