// Swarm engine: peer agents (no manager) work one goal in rounds.
// Each round: every agent works on its own (tools + private memory) and posts findings
// to the shared board → everyone proposes a next step → everyone votes → the winning
// plan assigns sub-tasks. Stops when most agents say the goal is done, or the round or
// token budget runs out; then a final synthesis turns the board into one answer.
// Every step is saved (agent_steps, board_posts) for the UI and traced in neatlogs.

import { randomUUID } from "crypto";
import fs from "fs";
import { fileURLToPath } from "url";
import { eq } from "drizzle-orm";
import { getDb } from "../core/db.js";
import { agentRuns, agentSteps, boardPosts, swarmAgents, swarms } from "../core/schema.js";
import { chat, type ChatMessage, type ToolDef } from "../core/model.js";
import { TokenBudgetExceeded, tokensLeft, withTokenBudget } from "../core/budget.js";
import { withSpan } from "../core/trace.js";
import { SWARM_TOOLS, type SwarmTool, type ToolGroup } from "./tools.js";
import { BENCHMARKS, scoreAnswer } from "./benchmarks.js";

const WORK_TURNS = 4; // model calls per agent per round
const BOARD_WINDOW = 14; // board posts each agent sees
const MEMORY_MAX = 1800; // chars of private memory kept

// Perspectives, not ranks: each agent brings a different way of attacking the goal.
const ANGLES = [
  { name: "Explorer", angle: "Try the most direct route to an answer quickly, then report what you found." },
  { name: "Skeptic", angle: "Check other agents' findings. Look for mistakes, missing cases and weak evidence; re-derive key results independently." },
  { name: "Builder", angle: "Compute and test. Prefer writing code to check or generate results over reasoning by hand." },
  { name: "Researcher", angle: "Look things up and bring outside facts and sources. Cite where each fact came from." },
  { name: "Contrarian", angle: "Take a different approach from the others so the swarm doesn't put all its eggs in one basket." },
];
const SOLO = { name: "Solo", angle: "You are working alone: explore, compute, research and verify your own work." };

const SWARM_PROMPT = fs
  .readFileSync(fileURLToPath(new URL("../agents/prompts/swarm-agent.md", import.meta.url)), "utf-8")
  .trim();

export interface LaunchOptions {
  goal: string;
  agentCount: number;
  tools: ToolGroup[];
  maxRounds: number;
  tokenBudget: number;
  benchmarkId?: string | null;
  compareGroup?: string | null;
  visitorId?: string | null;
}

type AgentRow = typeof swarmAgents.$inferSelect;

// ── Persistence helpers ─────────────────────────────────────────────────────────

const stepSeq = new Map<string, number>();
function writeStep(agentRunId: string, kind: "thinking" | "text" | "tool_call" | "tool_result" | "error", content: string, toolName?: string, isError = false) {
  const seq = stepSeq.get(agentRunId) ?? 0;
  stepSeq.set(agentRunId, seq + 1);
  getDb()
    .insert(agentSteps)
    .values({ id: randomUUID(), agentRunId, seq, kind, content, toolName: toolName ?? null, isError, ts: new Date() })
    .run();
}

async function post(swarmId: string, round: number, agentIdx: number | null, kind: typeof boardPosts.$inferInsert.kind, content: string) {
  await withSpan(`board:${kind}`, { swarm_id: swarmId, round, agent: agentIdx ?? "swarm", content: content.slice(0, 500) }, async () => {
    getDb()
      .insert(boardPosts)
      .values({ id: randomUUID(), swarmId, round, agentIdx, kind, content: content.slice(0, 2000), ts: new Date() })
      .run();
  });
}

function boardText(swarmId: string, limit = BOARD_WINDOW): string {
  const rows = getDb().select().from(boardPosts).where(eq(boardPosts.swarmId, swarmId)).all();
  const recent = rows.sort((a, b) => a.ts.getTime() - b.ts.getTime()).slice(-limit);
  if (!recent.length) return "(empty: nobody has posted yet)";
  return recent
    .map((p) => `[r${p.round}] ${p.agentIdx === null ? "SWARM" : `#${p.agentIdx}`} ${p.kind.toUpperCase()}: ${p.content}`)
    .join("\n");
}

function addUsage(swarmId: string, agent: AgentRow | null, tokens: number, costCents: number) {
  const db = getDb();
  const s = db.select().from(swarms).where(eq(swarms.id, swarmId)).get();
  if (s) db.update(swarms).set({ tokensUsed: s.tokensUsed + tokens, costCents: s.costCents + costCents }).where(eq(swarms.id, swarmId)).run();
  if (agent) {
    const a = db.select().from(swarmAgents).where(eq(swarmAgents.id, agent.id)).get();
    if (a) db.update(swarmAgents).set({ tokensUsed: a.tokensUsed + tokens }).where(eq(swarmAgents.id, agent.id)).run();
  }
}

const setAgent = (id: string, fields: Partial<typeof swarmAgents.$inferInsert>) =>
  getDb().update(swarmAgents).set(fields).where(eq(swarmAgents.id, id)).run();

const getAgent = (id: string) => getDb().select().from(swarmAgents).where(eq(swarmAgents.id, id)).get()!;

function parseJson<T>(text: string): T | null {
  const m = text.match(/\{[\s\S]*\}/);
  if (!m) return null;
  try {
    return JSON.parse(m[0]) as T;
  } catch {
    return null;
  }
}

// ── Launch ─────────────────────────────────────────────────────────────────────

export function launchSwarm(opts: LaunchOptions): string {
  const db = getDb();
  const id = randomUUID().slice(0, 12);
  const n = Math.min(Math.max(Math.round(opts.agentCount), 1), 5);
  db.insert(swarms)
    .values({
      id,
      goal: opts.goal,
      agentCount: n,
      tools: JSON.stringify(opts.tools),
      maxRounds: opts.maxRounds,
      tokenBudget: opts.tokenBudget,
      benchmarkId: opts.benchmarkId ?? null,
      compareGroup: opts.compareGroup ?? null,
      visitorId: opts.visitorId ?? null,
      startedAt: new Date(),
    })
    .run();
  const angles = n === 1 ? [SOLO] : ANGLES.slice(0, n);
  angles.forEach((a, i) => {
    const runId = randomUUID();
    db.insert(agentRuns)
      .values({ id: runId, runId: id, agent: `swarm:${a.name}`, task: opts.goal, startedAt: new Date() })
      .run();
    db.insert(swarmAgents)
      .values({ id: randomUUID(), swarmId: id, idx: i + 1, name: a.name, angle: a.angle, agentRunId: runId })
      .run();
  });
  runSwarm(id).catch((err) => {
    getDb()
      .update(swarms)
      .set({ status: "failed", error: err instanceof Error ? err.message : String(err), endedAt: new Date() })
      .where(eq(swarms.id, id))
      .run();
  });
  return id;
}

// ── Run ────────────────────────────────────────────────────────────────────────

async function runSwarm(swarmId: string) {
  const db = getDb();
  const swarm = db.select().from(swarms).where(eq(swarms.id, swarmId)).get()!;
  const agents = db.select().from(swarmAgents).where(eq(swarmAgents.swarmId, swarmId)).all().sort((a, b) => a.idx - b.idx);
  const enabled = new Set(JSON.parse(swarm.tools) as ToolGroup[]);
  const tools = SWARM_TOOLS.filter((t) => enabled.has(t.group));
  // Each agent gets an equal share of 90% of the budget; the rest is kept for the final answer.
  const shares = Object.fromEntries(agents.map((a) => [`agent-${a.idx}`, 0.9 / agents.length]));

  await withSpan(
    "swarm:run",
    { swarm_id: swarmId, goal: swarm.goal.slice(0, 300), agents: agents.length, max_rounds: swarm.maxRounds, token_budget: swarm.tokenBudget },
    async (span) => {
      db.update(swarms).set({ traceId: span.traceId || null }).where(eq(swarms.id, swarmId)).run();
      await withTokenBudget(
        async () => {
          await post(swarmId, 0, null, "system", `Swarm of ${agents.length} started. Goal: ${swarm.goal}`);
          for (let round = 1; round <= swarm.maxRounds; round++) {
            if (db.select().from(swarms).where(eq(swarms.id, swarmId)).get()?.status === "stopped") return;
            db.update(swarms).set({ round }).where(eq(swarms.id, swarmId)).run();

            // 1. Everyone works in parallel.
            await Promise.all(agents.map((a) => agentWork(swarmId, swarm.goal, getAgent(a.id), round, swarm.maxRounds, tools)));

            // 2. Sync: propose → vote → plan.
            const done = await syncRound(swarmId, swarm.goal, agents.map((a) => getAgent(a.id)), round, round === swarm.maxRounds);
            if (done) break;
            if (tokensLeft("synthesis") < swarm.tokenBudget * 0.15) {
              await post(swarmId, round, null, "system", "Budget nearly spent, so the swarm stops here and writes its answer.");
              break;
            }
          }
          await finalize(swarmId);
        },
        swarm.tokenBudget,
        shares
      );
      span.set({ "swarm.tokens_used": getDb().select().from(swarms).where(eq(swarms.id, swarmId)).get()?.tokensUsed ?? 0 });
    }
  );
}

async function agentWork(swarmId: string, goal: string, agent: AgentRow, round: number, maxRounds: number, tools: SwarmTool[]) {
  const runId = agent.agentRunId!;
  setAgent(agent.id, { status: "working" });
  writeStep(runId, "text", `— Round ${round} —${agent.assignment ? `\nAssignment: ${agent.assignment}` : ""}`);
  const posted: string[] = [];

  const ownTools: ToolDef[] = [
    ...tools.map(({ name, description, input_schema }) => ({ name, description, input_schema })),
    {
      name: "post_to_board",
      description: "Share a finding (with how you know it) or a question with the whole swarm.",
      input_schema: {
        type: "object",
        properties: { kind: { type: "string", enum: ["finding", "question"] }, content: { type: "string" } },
        required: ["kind", "content"],
      },
    },
    {
      name: "save_memory",
      description: "Add a note to your private memory for later rounds (others can't see it).",
      input_schema: { type: "object", properties: { note: { type: "string" } }, required: ["note"] },
    },
  ];

  await withSpan(`agent:${agent.name}`, { swarm_id: swarmId, agent: agent.name, round }, async () => {
    const messages: ChatMessage[] = [
      {
        role: "user",
        content: [
          `GOAL: ${goal}`,
          `ROUND ${round} of ${maxRounds}. You are agent #${agent.idx} "${agent.name}". Your angle: ${agent.angle}`,
          `YOUR ASSIGNMENT: ${agent.assignment ?? "No plan yet (first round): pick the most useful first step for your angle."}`,
          `YOUR MEMORY:\n${agent.memory || "(empty)"}`,
          `BOARD (latest posts):\n${boardText(swarmId)}`,
          `Work now (a few tool steps at most), save what you'll need to memory, then post 1–3 findings or questions to the board.`,
        ].join("\n\n"),
      },
    ];

    for (let turn = 0; turn < WORK_TURNS; turn++) {
      let res;
      try {
        res = await chat({ agent: `agent-${agent.idx}`, system: SWARM_PROMPT, messages, tools: ownTools, effort: "medium" });
      } catch (err) {
        if (err instanceof TokenBudgetExceeded) {
          writeStep(runId, "text", `Out of tokens for this run: ${err.message}`);
          break;
        }
        writeStep(runId, "error", err instanceof Error ? err.message : String(err), undefined, true);
        break;
      }
      addUsage(swarmId, agent, res.inTokens + res.outTokens, res.costCents);
      if (res.reasoning) writeStep(runId, "thinking", res.reasoning);
      if (res.text) writeStep(runId, "text", res.text);
      messages.push(res.message);
      if (!res.toolUses.length) break;

      for (const use of res.toolUses) {
        writeStep(runId, "tool_call", JSON.stringify(use.input, null, 2), use.name);
        let out: string;
        let isError = false;
        try {
          if (use.name === "post_to_board") {
            const kind = use.input["kind"] === "question" ? "question" : "finding";
            const content = String(use.input["content"] ?? "").trim();
            if (!content) throw new Error("content is empty");
            await post(swarmId, round, agent.idx, kind, content);
            posted.push(content);
            out = "posted";
          } else if (use.name === "save_memory") {
            const note = String(use.input["note"] ?? "").trim();
            const mem = `${getAgent(agent.id).memory}\n- (r${round}) ${note}`.trim();
            setAgent(agent.id, { memory: mem.length > MEMORY_MAX ? mem.slice(mem.length - MEMORY_MAX) : mem });
            out = "saved";
          } else {
            const tool = tools.find((t) => t.name === use.name);
            if (!tool) throw new Error(`tool ${use.name} is not enabled for this swarm`);
            const r = await withSpan(`tool:${use.name}`, { tool: use.name }, () => tool.run(use.input));
            out = typeof r === "string" ? r : JSON.stringify(r, null, 2);
          }
        } catch (err) {
          out = err instanceof Error ? err.message : String(err);
          isError = true;
        }
        writeStep(runId, "tool_result", out, use.name, isError);
        messages.push({ role: "tool", tool_call_id: use.id, content: isError ? `ERROR: ${out}` : out });
      }
    }

    // Every agent contributes at least one post per round.
    if (!posted.length) {
      const last = [...messages].reverse().find((m) => m.role === "assistant" && m.content);
      const text = last && last.role === "assistant" ? String(last.content ?? "") : "";
      if (text.trim()) await post(swarmId, round, agent.idx, "finding", text.trim().slice(0, 800));
    }
  });
  setAgent(agent.id, { status: "idle" });
}

interface Proposal {
  proposal: string;
  subtasks?: string[];
  done?: boolean;
  answer?: string;
  confidence?: string;
}

async function syncRound(swarmId: string, goal: string, agents: AgentRow[], round: number, lastRound: boolean): Promise<boolean> {
  return withSpan(`sync:round-${round}`, { swarm_id: swarmId, round }, async () => {
    const board = boardText(swarmId, 24);
    agents.forEach((a) => setAgent(a.id, { status: "syncing" }));

    // Propose.
    const proposals = await Promise.all(
      agents.map(async (a): Promise<Proposal | null> => {
        try {
          const res = await chat({
            agent: `agent-${a.idx}`,
            system: SWARM_PROMPT,
            effort: "low",
            maxTokens: 700,
            messages: [
              {
                role: "user",
                content: `GOAL: ${goal}\nYou are #${a.idx} "${a.name}" (${a.angle}).\nBOARD:\n${board}\n\n` +
                  `Round ${round} is over${lastRound ? " and it was the last round" : ""}. Reply with ONLY a JSON object:\n` +
                  `{"proposal": "what the swarm should do next and why (1-2 sentences)", ` +
                  `"subtasks": [${agents.length} short tasks, one per agent, in agent order #1..#${agents.length}], ` +
                  `"done": true if the board already contains a well-supported final answer, ` +
                  `"answer": "the current best answer, or empty", "confidence": "low|medium|high"}`,
              },
            ],
          });
          addUsage(swarmId, a, res.inTokens + res.outTokens, res.costCents);
          const p = parseJson<Proposal>(res.text);
          if (p?.proposal) {
            await post(swarmId, round, a.idx, "proposal", `${p.proposal}${p.done ? " [thinks we're done]" : ""}${p.answer ? `\nBest answer so far: ${p.answer} (${p.confidence ?? "?"})` : ""}`);
          }
          return p;
        } catch (err) {
          if (!(err instanceof TokenBudgetExceeded)) writeStep(a.agentRunId!, "error", String(err), undefined, true);
          return null;
        }
      })
    );

    const valid = proposals.map((p, i) => ({ p, agent: agents[i]! })).filter((x) => x.p?.proposal);
    if (!valid.length) return true;
    const doneVotes = valid.filter((x) => x.p!.done).length;

    // Vote (skipped for a single agent).
    let winner = valid[0]!;
    if (agents.length > 1 && valid.length > 1) {
      const options = valid.map((x) => `#${x.agent.idx}: ${x.p!.proposal}`).join("\n");
      const tally = new Map<number, number>();
      await Promise.all(
        agents.map(async (a) => {
          try {
            const res = await chat({
              agent: `agent-${a.idx}`,
              system: SWARM_PROMPT,
              effort: "low",
              maxTokens: 300,
              messages: [
                {
                  role: "user",
                  content: `GOAL: ${goal}\nYou are #${a.idx}. Proposals for the next round:\n${options}\n\n` +
                    `Vote for the best proposal that is not your own. Reply with ONLY JSON: {"vote": <agent number>, "why": "one short sentence"}`,
                },
              ],
            });
            addUsage(swarmId, a, res.inTokens + res.outTokens, res.costCents);
            const v = parseJson<{ vote: number; why?: string }>(res.text);
            const target = Number(v?.vote);
            if (target && target !== a.idx && valid.some((x) => x.agent.idx === target)) {
              tally.set(target, (tally.get(target) ?? 0) + 1);
              await post(swarmId, round, a.idx, "vote", `votes for #${target}${v?.why ? `: ${v.why}` : ""}`);
            }
          } catch {
            // a missed vote doesn't stop the swarm
          }
        })
      );
      const best = [...tally.entries()].sort((x, y) => y[1] - x[1] || x[0] - y[0])[0];
      if (best) winner = valid.find((x) => x.agent.idx === best[0]) ?? winner;
    }

    const done = doneVotes > valid.length / 2 || lastRound;
    if (!done) {
      const subtasks = winner.p!.subtasks ?? [];
      const lines = agents.map((a, i) => {
        const task = subtasks[i] ?? subtasks[i % Math.max(subtasks.length, 1)] ?? winner.p!.proposal;
        setAgent(a.id, { assignment: task });
        return `#${a.idx} ${a.name}: ${task}`;
      });
      await post(swarmId, round, null, "plan", `Plan for round ${round + 1} (proposed by #${winner.agent.idx}): ${winner.p!.proposal}\n${lines.join("\n")}`);
    } else if (!lastRound) {
      await post(swarmId, round, null, "system", `${doneVotes} of ${valid.length} agents think the goal is solved. Wrapping up.`);
    }
    agents.forEach((a) => setAgent(a.id, { status: "idle" }));
    return done;
  });
}

async function finalize(swarmId: string) {
  const db = getDb();
  const swarm = db.select().from(swarms).where(eq(swarms.id, swarmId)).get()!;
  let answer = "";
  let confidence = "low";
  await withSpan("swarm:final", { swarm_id: swarmId }, async () => {
    try {
      const res = await chat({
        agent: "synthesis",
        system: "You turn a swarm's message board into one final answer. Use only what the board supports. Prefer findings that were verified (computed or sourced) and not contradicted.",
        effort: "medium",
        maxTokens: 900,
        messages: [
          {
            role: "user",
            content: `GOAL: ${swarm.goal}\n\nBOARD:\n${boardText(swarmId, 60)}\n\n` +
              `Write the final answer. First line exactly "ANSWER: <the answer>". Second line "CONFIDENCE: low|medium|high". Then 2-4 short lines of evidence from the board.`,
          },
        ],
      });
      addUsage(swarmId, null, res.inTokens + res.outTokens, res.costCents);
      answer = res.text.trim();
      confidence = res.text.match(/CONFIDENCE:\s*(low|medium|high)/i)?.[1]?.toLowerCase() ?? "low";
    } catch (err) {
      answer = `ANSWER: (no final answer: ${err instanceof Error ? err.message : String(err)})`;
    }
  });
  await post(swarmId, swarm.round, null, "final", answer);

  const bench = swarm.benchmarkId ? BENCHMARKS.find((b) => b.id === swarm.benchmarkId) : undefined;
  const scored = bench ? scoreAnswer(bench, answer) : null;
  db.update(swarms)
    .set({
      status: "done",
      finalAnswer: answer,
      confidence,
      endedAt: new Date(),
      ...(scored ? { score: scored.correct ? 1 : 0, scoreNote: scored.note } : {}),
    })
    .where(eq(swarms.id, swarmId))
    .run();
  db.select().from(swarmAgents).where(eq(swarmAgents.swarmId, swarmId)).all().forEach((a) => {
    setAgent(a.id, { status: "done" });
    db.update(agentRuns).set({ status: "done", endedAt: new Date() }).where(eq(agentRuns.id, a.agentRunId!)).run();
  });
}

export function stopSwarm(swarmId: string) {
  getDb().update(swarms).set({ status: "stopped" }).where(eq(swarms.id, swarmId)).run();
}
